new file mode 100644
index 0000000000..49e50bca1b
--- /dev/null
+++ b/src/controllers/well-known.js
@@ -0,0 +1,46 @@
+'use strict';
+
+const nconf = require('nconf');
+
+const user = require('../user');
+const privileges = require('../privileges');
+
+module.exports = {
+	webfinger: async function (req, res, next) {
+		const resource = req.query.resource;
+
+		const hostname = nconf.get('url_parsed').hostname;
+		if (!resource || !resource.startsWith('acct:') || !resource.endsWith(`@${hostname}`)) {
+			return res.status(400).send('Bad Request');
+		}
+
+		const username = resource.slice('acct:'.length, -(`@${hostname}`).length);
+		const uid = await user.getUidByUsername(username);
+		if (!uid) {
+			return res.status(404).send('Not Found');
+		}
+
+		const allowed = await privileges.global.can('groups:view:users', req.uid);
+		if (!allowed) {
+			return res.status(403).send('Forbidden');
+		}
+
+		const userSlug = await user.getUserslug(uid);
+		const url = nconf.get('url');
+
+		res.status(200).json({
+			subject: resource,
+			aliases: [
+				`${url}/uid/${uid}`,
+				`${url}/user/${userSlug}`,
+			],
+			links: [
+				{
+					rel: 'http://webfinger.net/rel/profile-page',
+					type: 'text/html',
+					href: `${url}/user/${userSlug}`,
+				},
+			],
+		});
+	},
+};
