diff --git a/src/upgrades/1.19.3/rename_post_upload_hashes.js b/src/upgrades/1.19.3/rename_post_upload_hashes.js
new file mode 100644
index 000000000..89239b9a8
--- /dev/null
+++ b/src/upgrades/1.19.3/rename_post_upload_hashes.js
@@ -0,0 +1,54 @@
+'use strict';
+
+const crypto = require('crypto');
+
+const db = require('../../database');
+const batch = require('../../batch');
+
+const md5 = filename => crypto.createHash('md5').update(filename).digest('hex');
+
+module.exports = {
+	name: 'Rename object and sorted sets used in post uploads',
+	timestamp: Date.UTC(2022, 1, 10),
+	method: async function (context) {
+		const { progress } = context;
+
+		await batch.processSortedSet('posts:pid', async (pids) => {
+			await Promise.all(pids.map(async (pid) => {
+				const uploads = await db.getSortedSetMembers(`post:${pid}:uploads`);
+				const prefixedUploads = uploads.map(upload => upload.startsWith('files/') ? upload : `files/${upload}`);
+
+				if (uploads.length && uploads.length !== prefixedUploads.length) {
+					// Remove unprefixed entries and add prefixed ones
+					const toRemove = uploads.filter(upload => !upload.startsWith('files/'));
+					const toAdd = prefixedUploads.filter(upload => !uploads.includes(upload));
+					const now = Date.now();
+					const bulkAdd = toAdd.map(upload => [`upload:${md5(upload)}:pids`, now, pid]);
+					const bulkRemove = toRemove.map(upload => [`upload:${md5(upload)}:pids`, pid]);
+					await Promise.all([
+						db.sortedSetRemove(`post:${pid}:uploads`, toRemove),
+						toAdd.length ? db.sortedSetAdd(`post:${pid}:uploads`, toAdd.map(() => now), toAdd) : Promise.resolve(),
+						db.sortedSetAddBulk(bulkAdd),
+						db.sortedSetRemoveBulk(bulkRemove),
+					]);
+				}
+
+				// Rename the size objects to use the prefixed hash
+				await Promise.all(prefixedUploads.map(async (upload) => {
+					const oldKey = `upload:${md5(upload.replace(/^files\//, ''))}`;
+					const newKey = `upload:${md5(upload)}`;
+					const data = await db.getObject(oldKey);
+					if (data && !await db.getObject(newKey)) {
+						await db.setObject(newKey, data);
+						await db.delete(oldKey);
+					}
+				}));
+
+				progress.incr();
+			}));
+		}, {
+			progress,
+			batch: 100,
+		});
+	},
+};

