+
+import React from "react";
+
+export interface KeyCombo {
+    key: string;
+    ctrlKey?: boolean;
+    altKey?: boolean;
+    shiftKey?: boolean;
+    metaKey?: boolean;
+    ctrlOrCmd?: boolean;
+}
+
+function isLetterKey(key: string): boolean {
+    return /^[a-zA-Z]$/.test(key);
+}
+
+/**
+ * Checks whether a given keyboard event matches a key combination.
+ *
+ * A match requires the key to be equal (case-insensitively for letter keys)
+ * and the modifiers to be an exact match: no extra modifiers may be held.
+ * `ctrlOrCmd` is interpreted as the Command key on macOS and the Control
+ * key on Windows/Linux.
+ */
+export function isKeyComboMatch(
+    ev: KeyboardEvent | React.KeyboardEvent,
+    combo: KeyCombo,
+    onMac: boolean,
+): boolean {
+    // Keys like "a" and "A" should match regardless of capitalization.
+    const evKey = isLetterKey(ev.key) ? ev.key.toLowerCase() : ev.key;
+    const comboKey = isLetterKey(combo.key) ? combo.key.toLowerCase() : combo.key;
+    if (evKey !== comboKey) {
+        return false;
+    }
+
+    // Resolve the expected modifier state from the combo.
+    const expectedCtrl = !!combo.ctrlKey || (!!combo.ctrlOrCmd && !onMac);
+    const expectedAlt = !!combo.altKey;
+    const expectedMeta = !!combo.metaKey || (!!combo.ctrlOrCmd && onMac);
+
+    // Shift: for letter keys, Shift is what produces the uppercase form of
+    // the key, so it must not be required or forbidden just for that reason.
+    const expectedShift = !!combo.shiftKey;
+
+    // Exact modifier matching: no unrelated modifiers may be held.
+    if (ev.ctrlKey !== expectedCtrl) return false;
+    if (ev.altKey !== expectedAlt) return false;
+    if (ev.metaKey !== expectedMeta) return false;
+
+    if (isLetterKey(evKey)) {
+        // If the combo doesn't explicitly use Shift, allow Shift to be held
+        // (it simply capitalizes the letter) as long as nothing else is off.
+        if (expectedShift && !ev.shiftKey) return false;
+    } else if (ev.shiftKey !== expectedShift) {
+        return false;
+    }
+
+    return true;
+}

