+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+import React, { useState } from 'react';
+
+import { _t } from '../../../../languageHandler';
+import AccessibleButton from '../../elements/AccessibleButton';
+import Heading from '../../typography/Heading';
+import { DeviceWithVerification } from './types';
+
+interface Props {
+    device: DeviceWithVerification;
+    saveDeviceName: (deviceId: string, deviceName: string) => Promise<void>;
+}
+
+const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
+    const [isEditing, setIsEditing] = useState(false);
+    const [newName, setNewName] = useState(device.display_name ?? '');
+    const [isSaving, setIsSaving] = useState(false);
+    const [error, setError] = useState<string | null>(null);
+
+    const onRenameClick = () => {
+        setNewName(device.display_name ?? '');
+        setIsEditing(true);
+    };
+
+    const onCancel = () => {
+        setIsEditing(false);
+        setError(null);
+    };
+
+    const onSave = async () => {
+        setIsSaving(true);
+        setError(null);
+        try {
+            // only persist if the name has changed; empty string is a valid value
+            if (newName !== device.display_name) {
+                await saveDeviceName(device.device_id, newName);
+            }
+            setIsEditing(false);
+        } catch (e) {
+            setError(_t('Failed to set display name.'));
+        } finally {
+            setIsSaving(false);
+        }
+    };
+
+    const displayName = device.display_name ?? device.device_id;
+
+    if (isEditing) {
+        return <div data-testid='device-detail-heading-edit-view'>
+            <Heading size='h3'>{ _t('Rename session') }</Heading>
+            <input
+                data-testid='device-detail-heading-input'
+                type='text'
+                value={newName}
+                maxLength={100}
+                onChange={(e) => setNewName(e.target.value)}
+            />
+            <p className='mx_DeviceDetailHeading_warning'>
+                { _t('Session names may be visible to other people you communicate with.') }
+            </p>
+            { error && <p className='mx_DeviceDetailHeading_error' data-testid='device-detail-heading-error'>{ error }</p> }
+            <div className='mx_DeviceDetailHeading_actions'>
+                <AccessibleButton
+                    kind='primary'
+                    data-testid='device-detail-heading-save-btn'
+                    disabled={isSaving}
+                    onClick={onSave}
+                >
+                    { _t('Save') }
+                </AccessibleButton>
+                <AccessibleButton
+                    kind='link'
+                    data-testid='device-detail-heading-cancel-btn'
+                    disabled={isSaving}
+                    onClick={onCancel}
+                >
+                    { _t('Cancel') }
+                </AccessibleButton>
+            </div>
+        </div>;
+    }
+
+    return <div data-testid='device-detail-heading-read-view'>
+        <Heading size='h3'>{ displayName }</Heading>
+        <AccessibleButton
+            kind='link_inline'
+            data-testid='device-detail-heading-rename-btn'
+            onClick={onRenameClick}
+        >
+            { _t('Rename') }
+        </AccessibleButton>
+    </div>;
+};
+
+export default DeviceDetailHeading;
