--- /dev/null
+++ b/src/components/views/rooms/EventPreview.tsx
@@ -0,0 +1,122 @@
+/*
+ * Copyright 2024 New Vector Ltd.
+ * Copyright 2024 The Matrix.org Foundation C.I.C.
+ *
+ * SPDX-License-Identifier: AGPL-3.0-only OR GPL-3.0-only
+ * Please see LICENSE files in the repository root for full details.
+ */
+
+import React, { JSX, useContext, useState } from "react";
+import { IContent, M_POLL_START, MatrixEvent, MatrixEventEvent, MsgType } from "matrix-js-sdk/src/matrix";
+import classNames from "classnames";
+
+import { _t } from "../../../languageHandler";
+import { useAsyncMemo } from "../../../hooks/useAsyncMemo";
+import MatrixClientContext from "../../../contexts/MatrixClientContext";
+import { useTypedEventEmitter } from "../../../hooks/useEventEmitter";
+import { MessagePreviewStore } from "../../../stores/room-list/MessagePreviewStore";
+
+/**
+ * A preview of an event: the preview text and an optional message type prefix.
+ */
+export type Preview = [preview: string, prefix: string | null];
+
+/**
+ * The props for the {@link EventPreview} component.
+ */
+interface IProps extends React.HTMLAttributes<HTMLSpanElement> {
+    /**
+     * The event to preview
+     */
+    mxEvent: MatrixEvent;
+    className?: string;
+}
+
+/**
+ * A component that renders a preview of an event with an optional message type prefix.
+ */
+export function EventPreview({ mxEvent, className, ...props }: IProps): JSX.Element | null {
+    const preview = useEventPreview(mxEvent);
+    if (!preview) return null;
+    return <EventPreviewTile preview={preview} className={className} {...props} />;
+}
+
+/**
+ * The props for the {@link EventPreviewTile} component.
+ */
+interface IPreviewTileProps extends React.HTMLAttributes<HTMLSpanElement> {
+    /**
+     * The preview to render: the preview text and an optional prefix.
+     */
+    preview: Preview;
+    className?: string;
+}
+
+/**
+ * A component that renders a preview string with an optional prefix in a styled span.
+ */
+export function EventPreviewTile({ preview, className, ...props }: IPreviewTileProps): JSX.Element | null {
+    if (!preview) return null;
+    const [previewText, prefix] = preview;
+    return (
+        <span className={classNames("mx_EventPreview", className)} {...props}>
+            {prefix && <span className="mx_EventPreview_prefix">{prefix}</span>}
+            {previewText}
+        </span>
+    );
+}
+
+/**
+ * A hook that generates a preview string and an optional message type prefix for a given event.
+ * The preview is regenerated when the event is replaced, decrypted or its content is edited.
+ * @param mxEvent The event to generate the preview for.
+ * @returns The preview (text and optional prefix) or null if no preview can be generated.
+ */
+export function useEventPreview(mxEvent: MatrixEvent | undefined): Preview | null {
+    const cli = useContext(MatrixClientContext);
+
+    // track the content as a means to regenerate the preview upon edits & decryption
+    const [content, setContent] = useState<IContent | undefined>(mxEvent?.getContent());
+    useTypedEventEmitter(mxEvent, MatrixEventEvent.Replaced, () => {
+        setContent(mxEvent?.getContent());
+    });
+    const awaitDecryption = mxEvent?.shouldAttemptDecryption() || mxEvent?.isBeingDecrypted();
+    useTypedEventEmitter(awaitDecryption ? mxEvent : undefined, MatrixEventEvent.Decrypted, () => {
+        setContent(mxEvent?.getContent());
+    });
+
+    return useAsyncMemo<Preview | null>(async (): Promise<Preview | null> => {
+        if (!mxEvent || mxEvent.isRedacted() || mxEvent.isDecryptionFailure()) return null;
+        await cli.decryptEventIfNeeded(mxEvent);
+        const preview = MessagePreviewStore.instance.generatePreviewForEvent(mxEvent);
+        if (!preview) return null;
+        return [preview, getPreviewPrefix(mxEvent.getType(), mxEvent.getContent().msgtype as MsgType)];
+    }, [mxEvent, content]);
+}
+
+/**
+ * Get the prefix for the preview based on the type and the message type.
+ * @param type The event type.
+ * @param msgType The message type.
+ * @returns The localized prefix or null if the event type has no prefix.
+ */
+function getPreviewPrefix(type: string, msgType: MsgType): string | null {
+    switch (type) {
+        case M_POLL_START.name:
+            return _t("event_preview|prefix|poll");
+        default:
+    }
+
+    switch (msgType) {
+        case MsgType.Audio:
+            return _t("event_preview|prefix|audio");
+        case MsgType.Image:
+            return _t("event_preview|prefix|image");
+        case MsgType.Video:
+            return _t("event_preview|prefix|video");
+        case MsgType.File:
+            return _t("event_preview|prefix|file");
+        default:
+            return null;
+    }
+}
