+Unless required by applicable law or agreed to in writing, software
+distributed under the License is distributed on an "AS IS" BASIS,
+WITHOUT WARRANTIES OR CONDITIONS OF ANY KIND, either express or implied.
+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+import { MatrixClient, MatrixEvent, RelationType } from "matrix-js-sdk/src/matrix";
+import { TypedEventEmitter } from "matrix-js-sdk/src/models/typed-event-emitter";
+
+import { VoiceBroadcastInfoEventType, VoiceBroadcastInfoState } from "..";
+
+export enum VoiceBroadcastRecordingEvent {
+    StateChanged = "StateChanged",
+}
+
+type EventHandlerMap = {
+    [VoiceBroadcastRecordingEvent.StateChanged]: (state: VoiceBroadcastInfoState) => void;
+};
+
+export class VoiceBroadcastRecording extends TypedEventEmitter<VoiceBroadcastRecordingEvent, EventHandlerMap> {
+    private readonly client: MatrixClient;
+    private readonly infoEvent: MatrixEvent;
+    private _state: VoiceBroadcastInfoState;
+
+    constructor(client: MatrixClient, infoEvent: MatrixEvent, state: VoiceBroadcastInfoState) {
+        super();
+        this.client = client;
+        this.infoEvent = infoEvent;
+        this._state = this.getInitialState(client, infoEvent, state);
+    }
+
+    private getInitialState(
+        client: MatrixClient,
+        infoEvent: MatrixEvent,
+        state: VoiceBroadcastInfoState,
+    ): VoiceBroadcastInfoState {
+        const room = client.getRoom(infoEvent.getRoomId());
+        if (!room) {
+            return state;
+        }
+
+        const timelineSet = room.getUnfilteredTimelineSet();
+        const relations = timelineSet.relations?.getChildEventsForEvent(
+            infoEvent.getId(),
+            RelationType.Reference,
+            VoiceBroadcastInfoEventType,
+        );
+        const relatedEvents = relations?.getRelations();
+
+        if (relatedEvents) {
+            for (const event of relatedEvents) {
+                const eventState = event.getContent()?.state as VoiceBroadcastInfoState;
+                if (eventState === VoiceBroadcastInfoState.Stopped) {
+                    return VoiceBroadcastInfoState.Stopped;
+                }
+            }
+        }
+
+        return state;
+    }
+
+    public get state(): VoiceBroadcastInfoState {
+        return this._state;
+    }
+
+    public getRoomId(): string {
+        return this.infoEvent.getRoomId();
+    }
+
+    public getId(): string {
+        return this.infoEvent.getId();
+    }
+
+    public stop(): Promise<void> {
+        return this.client.sendStateEvent(
+            this.getRoomId(),
+            VoiceBroadcastInfoEventType,
+            {
+                state: VoiceBroadcastInfoState.Stopped,
+                ["m.relates_to"]: {
+                    rel_type: RelationType.Reference,
+                    event_id: this.getId(),
+                },
+            },
+            this.client.getUserId(),
+        ).then(() => {
+            this._state = VoiceBroadcastInfoState.Stopped;
+            this.emit(VoiceBroadcastRecordingEvent.StateChanged, this._state);
+        });
+    }
+
+    public destroy(): void {
+        this.removeAllListeners(VoiceBroadcastRecordingEvent.StateChanged);
+    }
+}
