+See the License for the specific language governing permissions and
+limitations under the License.
+*/
+
+import { MatrixClient, MatrixEvent } from "matrix-js-sdk/src/matrix";
+import { TypedEventEmitter } from "matrix-js-sdk/src/models/typed-event-emitter";
+
+import { VoiceBroadcastInfoState } from "..";
+import { VoiceBroadcastRecording } from "../models";
+
+export enum VoiceBroadcastRecordingsStoreEvents {
+    CurrentChanged = "CurrentChanged",
+}
+
+type EventHandlerMap = {
+    [VoiceBroadcastRecordingsStoreEvents.CurrentChanged]: (current: VoiceBroadcastRecording | null) => void;
+};
+
+export class VoiceBroadcastRecordingsStore extends TypedEventEmitter<VoiceBroadcastRecordingsStoreEvents, EventHandlerMap> {
+    private static instance_: VoiceBroadcastRecordingsStore | null = null;
+
+    private readonly recordings: Map<string, VoiceBroadcastRecording> = new Map();
+    private _current: VoiceBroadcastRecording | null = null;
+
+    public static get instance(): VoiceBroadcastRecordingsStore {
+        if (!this.instance_) {
+            this.instance_ = new VoiceBroadcastRecordingsStore();
+        }
+        return this.instance_;
+    }
+
+    public get current(): VoiceBroadcastRecording | null {
+        return this._current;
+    }
+
+    public setCurrent(current: VoiceBroadcastRecording | null): void {
+        this._current = current;
+        this.emit(VoiceBroadcastRecordingsStoreEvents.CurrentChanged, current);
+    }
+
+    public getByInfoEvent(infoEvent: MatrixEvent): VoiceBroadcastRecording | null {
+        return this.recordings.get(infoEvent.getId()) ?? null;
+    }
+
+    public getOrCreateRecording(
+        client: MatrixClient,
+        infoEvent: MatrixEvent,
+        state: VoiceBroadcastInfoState,
+    ): VoiceBroadcastRecording {
+        let recording = this.recordings.get(infoEvent.getId());
+        if (!recording) {
+            recording = new VoiceBroadcastRecording(client, infoEvent, state);
+            this.recordings.set(infoEvent.getId(), recording);
+        }
+        return recording;
+    }
+}
