+// applyDefaults sets the default values for the tracing configuration
+// when they have not been explicitly set (either via config file or env).
+func (c *TracingConfig) applyDefaults(v *viper.Viper) {
+	if v.IsSet("tracing.samplingRatio") {
+		c.SamplingRatio = v.GetFloat64("tracing.samplingRatio")
+	} else {
+		c.SamplingRatio = 1
+	}
+
+	if v.IsSet("tracing.propagators") {
+		c.Propagators = propagatorsFromValue(v.Get("tracing.propagators"))
+	} else {
+		c.Propagators = []TracingPropagator{TracingPropagatorTraceContext, TracingPropagatorBaggage}
+	}
