+
+func propagatorsFromValue(v any) []TracingPropagator {
+	var out []TracingPropagator
+	switch p := v.(type) {
+	case []TracingPropagator:
+		out = p
+	case []string:
+		for _, s := range p {
+			out = append(out, TracingPropagator(s))
+		}
+	case string:
+		for _, s := range strings.Fields(p) {
+			out = append(out, TracingPropagator(s))
+		}
+	}
+	return out
 }

