+// validate ensures the redis cache configuration is within reasonable ranges.
+func (c *RedisCacheConfig) validate() error {
+	if c.Port < 0 || c.Port > 65535 {
+		return fmt.Errorf("invalid redis port: %d", c.Port)
+	}
+
+	if c.DB < 0 {
+		return fmt.Errorf("invalid redis db: %d", c.DB)
+	}
+
+	if c.PoolSize < 0 {
+		return fmt.Errorf("invalid redis pool size: %d", c.PoolSize)
+	}
+
+	if c.MinIdleConns < 0 {
+		return fmt.Errorf("invalid redis min idle conns: %d", c.MinIdleConns)
+	}
+
+	if c.MinIdleConns > c.PoolSize {
+		return fmt.Errorf("invalid redis min idle conns (%d) greater than pool size (%d)", c.MinIdleConns, c.PoolSize)
+	}
+
+	return nil
+}
+
+// TLSConfig returns a *tls.Config when TLS is enabled for the redis connection.
+func (c *RedisCacheConfig) TLSConfig() *tls.Config {
+	if !c.TLS {
+		return nil
+	}
+
+	return &tls.Config{
+		MinVersion: tls.VersionTLS12,
+	}
 }
