+// ErrorHandler is a grpc gateway error handler which clears the authentication
+// cookies on the response when the error is an unauthenticated error and the
+// request contained authentication cookies. This prevents clients from
+// continuing to send expired or invalid credentials with every request.
+// In all cases it delegates to the default error handler to produce the
+// standard error response.
+func (m Middleware) ErrorHandler(ctx context.Context, sm *runtime.ServeMux, ms runtime.Marshaler, w http.ResponseWriter, r *http.Request, err error) {
+	if s, ok := status.FromError(err); ok && s.Code() == codes.Unauthenticated {
+		for _, cookieName := range []string{stateCookieKey, tokenCookieKey} {
+			if _, cookieErr := r.Cookie(cookieName); cookieErr == nil {
+				http.SetCookie(w, &http.Cookie{
+					Name:   cookieName,
+					Value:  "",
+					Domain: m.config.Domain,
+					Path:   "/",
+					MaxAge: -1,
+				})
+			}
+		}
+	}
+
+	runtime.DefaultHTTPErrorHandler(ctx, sm, ms, w, r, err)
+}

