+	// CacheControlHeader is the name of the HTTP/gRPC header used to convey
+	// cache directives (e.g. "no-store") on requests.
+	CacheControlHeader = "cache-control"
+
+	// CacheControlNoStore is the Cache-Control directive which indicates that
+	// the response/request must not be stored in (or served from) any cache.
+	CacheControlNoStore = "no-store"
