+
+// hasNoStoreDirective reports whether the provided Cache-Control header value
+// contains the "no-store" directive. Matching is case-insensitive and works
+// with combined directives (e.g. "max-age=0, no-store").
+func hasNoStoreDirective(value string) bool {
+	if value == "" {
+		return false
+	}
+
+	for _, directive := range strings.Split(value, ",") {
+		// a directive may be "key=value" or a bare "key"; the value of
+		// interest ("no-store") is a bare token so compare the part
+		// before any '=' (which no-store will never have) case-insensitively.
+		if idx := strings.Index(directive, "="); idx != -1 {
+			directive = directive[:idx]
+		}
+
+		if strings.EqualFold(strings.TrimSpace(directive), CacheControlNoStore) {
+			return true
+		}
+	}
+
+	return false
+}
