+// ConnectionString returns the database connection URL. When a URL is
+// explicitly configured it takes precedence; otherwise the URL is derived
+// from the individual protocol/host/port/user/password/name fields with
+// sensible engine-specific defaults applied.
+func (c DatabaseConfig) ConnectionString() (string, error) {
+	if c.URL != "" {
+		return c.URL, nil
+	}
+
+	if c.Protocol == 0 {
+		return "", fmt.Errorf("%s cannot be empty", dbProtocol)
+	}
+
+	if _, ok := databaseProtocolToString[c.Protocol]; !ok {
+		return "", fmt.Errorf("%s must be one of: sqlite3, postgres, mysql (got: %s)", dbProtocol, c.Protocol.String())
+	}
+
+	if c.Name == "" {
+		return "", fmt.Errorf("%s cannot be empty", dbName)
+	}
+
+	if c.Protocol != DatabaseProtocolSQLite && c.Host == "" {
+		return "", fmt.Errorf("%s cannot be empty", dbHost)
+	}
+
+	var (
+		port = c.Port
+		user = c.User
+		pass = c.Password
+	)
+
+	switch c.Protocol {
+	case DatabaseProtocolSQLite:
+		return fmt.Sprintf("file:%s", c.Name), nil
+
+	case DatabaseProtocolPostgres:
+		if port == 0 {
+			port = 5432
+		}
+
+		return fmt.Sprintf("postgres://%s:%s@%s:%d/%s", user, pass, c.Host, port, c.Name), nil
+
+	case DatabaseProtocolMySQL:
+		if port == 0 {
+			port = 3306
+		}
+
+		return fmt.Sprintf("mysql://%s:%s@%s:%d/%s", user, pass, c.Host, port, c.Name), nil
+	}
+
+	return "", fmt.Errorf("%s must be one of: sqlite3, postgres, mysql (got: %s)", dbProtocol, c.Protocol.String())
+}
