+// parseListenPorts parses a listen endpoint string like "127.0.0.1:22",
+// "*:80" or "[::1]:443" into a ListenPort struct.
+// IPv6 addresses keep their brackets and the string is split on the last
+// colon so the port is always the last component.
+func (l *base) parseListenPorts(s string) models.ListenPort {
+	lp := models.ListenPort{PortScanSuccessOn: []string{}}
+	if i := strings.LastIndex(s, ":"); i >= 0 {
+		lp.Address = s[:i]
+		lp.Port = s[i+1:]
+	} else {
+		lp.Address = s
+	}
+	return lp
+}
+
+// detectScanDest returns the unique "ip:port" destinations to probe for
+// reachability, derived from the listening endpoints of affected processes.
+// A wildcard address "*" is expanded to the host's IPv4 addresses.
+func (l *base) detectScanDest() []string {
+	dests := []string{}
+	seen := map[string]struct{}{}
+	for _, p := range l.Packages {
+		for _, proc := range p.AffectedProcs {
+			for _, lp := range proc.ListenPorts {
+				addrs := []string{lp.Address}
+				if lp.Address == "*" {
+					addrs = l.ServerInfo.IPv4Addrs
+				}
+				for _, addr := range addrs {
+					dest := addr + ":" + lp.Port
+					if _, ok := seen[dest]; ok {
+						continue
+					}
+					seen[dest] = struct{}{}
+					dests = append(dests, dest)
+				}
+			}
+		}
+	}
+	return dests
+}
+
+// scanTCP returns true if a TCP connection to ip:port succeeds within a
+// short timeout.
+func (l *base) scanTCP(dest string) bool {
+	conn, err := net.DialTimeout("tcp", dest, 1*time.Second)
+	if err != nil {
+		return false
+	}
+	_ = conn.Close()
+	return true
+}
+
+// updatePortStatus probes the listening endpoints of affected processes and
+// fills in PortScanSuccessOn in place.
+func (l *base) updatePortStatus(listenIPPorts []string) {
+	for name, p := range l.Packages {
+		for i, proc := range p.AffectedProcs {
+			for j, lp := range proc.ListenPorts {
+				p.AffectedProcs[i].ListenPorts[j].PortScanSuccessOn =
+					l.findPortScanSuccessOn(listenIPPorts, lp)
+			}
+		}
+		l.Packages[name] = p
+	}
+}
+
+// findPortScanSuccessOn returns the IPv4 addresses on which the given
+// listening endpoint was confirmed reachable. It always returns a
+// non-nil slice.
+func (l *base) findPortScanSuccessOn(listenIPPorts []string, searchListenPort models.ListenPort) []string {
+	successOn := []string{}
+	seen := map[string]struct{}{}
+	for _, dest := range listenIPPorts {
+		if !strings.HasSuffix(dest, ":"+searchListenPort.Port) {
+			continue
+		}
+		ip := dest[:len(dest)-len(searchListenPort.Port)-1]
+		if searchListenPort.Address != "*" && ip != searchListenPort.Address {
+			continue
+		}
+		if _, ok := seen[ip]; ok {
+			continue
+		}
+		seen[ip] = struct{}{}
+		successOn = append(successOn, ip)
+	}
+	return successOn
+}
