+// RemoveNonRunningKernelPackages removes kernel source packages and kernel
+// binaries whose name or version does not match the running kernel's release
+// string (uname -r) from the scan result.
+// Only kernel source packages whose name and version match the running
+// kernel's release string, and only kernel binaries containing the running
+// kernel's release string, are kept for vulnerability detection and
+// reporting.
+func (r *ScanResult) RemoveNonRunningKernelPackages() {
+	if r.RunningKernel.Release == "" {
+		return
+	}
+
+	packs := make(Packages, len(r.Packages))
+	for name, pack := range r.Packages {
+		if IsKernelBinaryPackage(name) {
+			if !strings.Contains(name, r.RunningKernel.Release) {
+				continue
+			}
+		}
+		packs[name] = pack
+	}
+	r.Packages = packs
+
+	srcPacks := make(SrcPackages, len(r.SrcPackages))
+	for name, srcPack := range r.SrcPackages {
+		if IsKernelSourcePackage(r.Family, RenameKernelSourcePackageName(r.Family, name)) {
+			// Keep only the source package whose name matches the running
+			// kernel's release string.
+			if !strings.Contains(name, r.RunningKernel.Release) {
+				continue
+			}
+			// Keep only the binaries containing the running kernel's release
+			// string.
+			binaryNames := make([]string, 0, len(srcPack.BinaryNames))
+			for _, bn := range srcPack.BinaryNames {
+				if strings.Contains(bn, r.RunningKernel.Release) {
+					binaryNames = append(binaryNames, bn)
+				}
+			}
+			srcPack.BinaryNames = binaryNames
+			if len(binaryNames) == 0 {
+				continue
+			}
+		}
+		srcPacks[name] = srcPack
+	}
+	r.SrcPackages = srcPacks
+}
