+
+package model
+
+import (
+	"sync"
+
+	"github.com/gravitational/trace"
+	"github.com/sashabaranov/go-openai"
+	"github.com/tiktoken-go/tokenizer/codec"
+)
+
+// TokenCount tracks the number of tokens used by a single invocation of the
+// agent, aggregating prompt and completion counters across all steps.
+type TokenCount struct {
+	prompts     TokenCounters
+	completions TokenCounters
+}
+
+// NewTokenCount creates a new empty TokenCount.
+func NewTokenCount() *TokenCount {
+	return &TokenCount{
+		prompts:     make(TokenCounters, 0),
+		completions: make(TokenCounters, 0),
+	}
+}
+
+// AddPromptCounter adds a prompt-side token counter to the TokenCount.
+// A nil counter is ignored.
+func (t *TokenCount) AddPromptCounter(prompt TokenCounter) {
+	if prompt == nil {
+		return
+	}
+
+	t.prompts = append(t.prompts, prompt)
+}
+
+// AddCompletionCounter adds a completion-side token counter to the TokenCount.
+// A nil counter is ignored.
+func (t *TokenCount) AddCompletionCounter(completion TokenCounter) {
+	if completion == nil {
+		return
+	}
+
+	t.completions = append(t.completions, completion)
+}
+
+// CountAll returns the total number of prompt and completion tokens used,
+// in the order (promptTotal, completionTotal).
+func (t *TokenCount) CountAll() (int, int) {
+	return t.prompts.CountAll(), t.completions.CountAll()
+}
+
+// TokenCounter is the contract for a token counter.
+type TokenCounter interface {
+	// TokenCount returns the number of tokens counted by this counter.
+	TokenCount() int
+}
+
+// TokenCounters is a collection of token counters.
+type TokenCounters []TokenCounter
+
+// CountAll returns the sum of the token counts of all contained counters.
+func (t TokenCounters) CountAll() int {
+	count := 0
+	for _, counter := range t {
+		count += counter.TokenCount()
+	}
+
+	return count
+}
+
+// StaticTokenCounter is a fixed-value token counter, e.g. for a prompt or a
+// fully completed response.
+type StaticTokenCounter struct {
+	count int
+}
+
+// TokenCount returns the stored value of the static counter.
+func (s *StaticTokenCounter) TokenCount() int {
+	return s.count
+}
+
+// NewPromptTokenCounter computes the prompt token usage for a list of
+// messages using the cl100k_base tokenizer.
+func NewPromptTokenCounter(messages []openai.ChatCompletionMessage) (*StaticTokenCounter, error) {
+	// Cl100k is used by GPT-3 and GPT-4.
+	tokenizer := codec.NewCl100kBase()
+
+	count := 0
+	for _, message := range messages {
+		tokens, _, err := tokenizer.Encode(message.Content)
+		if err != nil {
+			return nil, trace.Wrap(err)
+		}
+
+		count += perMessage + perRole + len(tokens)
+	}
+
+	return &StaticTokenCounter{count: count}, nil
+}
+
+// NewSynchronousTokenCounter computes the completion token usage for a full,
+// non-streamed response using the cl100k_base tokenizer.
+func NewSynchronousTokenCounter(completion string) (*StaticTokenCounter, error) {
+	// Cl100k is used by GPT-3 and GPT-4.
+	tokenizer := codec.NewCl100kBase()
+
+	tokens, _, err := tokenizer.Encode(completion)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+
+	return &StaticTokenCounter{count: perRequest + len(tokens)}, nil
+}
+
+// AsynchronousTokenCounter is a streaming-aware counter for completion
+// tokens. Add increments the count while streaming, and TokenCount
+// finalizes and returns the total.
+type AsynchronousTokenCounter struct {
+	// count is the number of streamed tokens received so far.
+	count int
+
+	// finished indicates the counter has been finalized by TokenCount.
+	finished bool
+
+	// mutex protects count and finished.
+	mutex sync.Mutex
+}
+
+// Add increments the streamed token count by one. It returns an error if the
+// counter has already been finalized by a call to TokenCount.
+func (a *AsynchronousTokenCounter) Add() error {
+	a.mutex.Lock()
+	defer a.mutex.Unlock()
+
+	if a.finished {
+		return trace.Errorf("cannot add to a finished token counter")
+	}
+
+	a.count++
+	return nil
+}
+
+// TokenCount finalizes the counter and returns the total token count
+// including the per-request overhead. It is idempotent and non-blocking;
+// subsequent calls to Add return an error.
+func (a *AsynchronousTokenCounter) TokenCount() int {
+	a.mutex.Lock()
+	defer a.mutex.Unlock()
+
+	if !a.finished {
+		a.finished = true
+	}
+
+	return perRequest + a.count
+}
+
+// NewAsynchronousTokenCounter initializes an AsynchronousTokenCounter with
+// the tokenized starting fragment of a streamed completion.
+func NewAsynchronousTokenCounter(start string) (*AsynchronousTokenCounter, error) {
+	// Cl100k is used by GPT-3 and GPT-4.
+	tokenizer := codec.NewCl100kBase()
+
+	tokens, _, err := tokenizer.Encode(start)
+	if err != nil {
+		return nil, trace.Wrap(err)
+	}
+
+	return &AsynchronousTokenCounter{
+		count: len(tokens),
+	}, nil
+}
+
