+// byteBuffer is a byte ring buffer with a fixed backing storage that is
+// allocated on first use and never shrunk.
+type byteBuffer struct {
+	buf   []byte
+	start int
+	end   int
+	max   int
+}
+
+// newByteBuffer returns a new, empty byteBuffer.
+func newByteBuffer() *byteBuffer {
+	return &byteBuffer{}
+}
+
+// reserve ensures that the buffer has enough free space to accommodate
+// n bytes, reallocating the internal storage if needed.
+// If the current capacity is insufficient, a new capacity is computed by
+// doubling the current one until it meets the requirement, then the
+// storage is reallocated and the existing buffered data is restored.
+func (b *byteBuffer) reserve(n int) {
+	if b.buf == nil {
+		b.buf = make([]byte, 16*1024)
+		return
+	}
+	free := len(b.buf) - b.end + b.start
+	if free >= n {
+		return
+	}
+	capacity := len(b.buf)
+	for capacity < b.end+n {
+		capacity *= 2
+	}
+	newBuf := make([]byte, capacity)
+	copy(newBuf, b.buf[b.start:b.end])
+	b.start = 0
+	b.end = b.end - b.start
+	b.buf = newBuf
+}
+
+// len returns the number of bytes currently buffered.
+func (b *byteBuffer) len() int {
+	return b.end - b.start
+}
+
+// buffered returns up to two contiguous readable slices starting at the
+// head of the buffer. When data wraps, both slices are non-empty,
+// otherwise the second slice is empty.
+// The sum of their lengths equals len().
+func (b *byteBuffer) buffered() (b1 []byte, b2 []byte) {
+	if b.buf == nil {
+		return nil, nil
+	}
+	if b.start == b.end {
+		return nil, nil
+	}
+	if b.start < b.end {
+		return b.buf[b.start:b.end], nil
+	}
+	return b.buf[b.start:], b.buf[:b.end]
+}
+
+// free returns up to two contiguous writable slices starting at the tail
+// of the buffer. When the free space wraps, both slices are non-empty,
+// otherwise the second slice is empty.
+// The sum of their lengths equals the capacity minus len().
+// If the buffer is empty, the two slices together represent the full
+// free space.
+func (b *byteBuffer) free() (f1 []byte, f2 []byte) {
+	if b.buf == nil {
+		b.reserve(0)
+	}
+	if b.start == b.end {
+		// Empty buffer: the whole storage is free, returned as two slices
+		// that together represent the full free space.
+		return b.buf[b.end:], b.buf[:b.start]
+	}
+	if b.start < b.end {
+		// Free space is contiguous, from end to start.
+		return b.buf[b.end:], b.buf[:b.start]
+	}
+	// Free space wraps: from end to the end of the buffer, then from the
+	// beginning to start.
+	return b.buf[b.end:], b.buf[:b.start]
+}
+
+// write appends p to the tail of the buffer, without exceeding the
+// maximum allowed buffer size. If the buffer has already reached or
+// surpassed the limit, write returns zero.
+func (b *byteBuffer) write(p []byte) int {
+	if b.max > 0 && b.len() >= b.max {
+		return 0
+	}
+	b.reserve(len(p))
+	f1, f2 := b.free()
+	n := 0
+	if len(f1) >= len(p) {
+		n = copy(f1, p)
+	} else {
+		n = copy(f1, p)
+		n += copy(f2, p[n:])
+	}
+	b.end = (b.end + n) % len(b.buf)
+	return n
+}
+
+// advance moves the buffer's start position forward by n, discarding
+// that amount of data from the head. If the advancement passes the
+// current end, the end position is updated to match the new start,
+// maintaining a consistent empty state.
+func (b *byteBuffer) advance(n int) {
+	if b.buf == nil {
+		return
+	}
+	b.start += n
+	if b.start >= b.end {
+		b.end = b.start
+	}
+	if b.start >= len(b.buf) {
+		b.start -= len(b.buf)
+		b.end -= len(b.buf)
+	}
+}
+
+// read fills p with as much data as available from the buffer, using the
+// result of buffered to perform the copies. It then advances the internal
+// buffer position by the total number of bytes copied and returns it.
+func (b *byteBuffer) read(p []byte) int {
+	b1, b2 := b.buffered()
+	n := copy(p, b1)
+	if n < len(p) {
+		n += copy(p[n:], b2)
+	}
+	b.advance(n)
+	return n
+}
