+// Package resumption implements the primitives for resuming connections
+// that have been dropped, as described in RFD 0150.
+package resumption
+
+import (
+	"errors"
+	"io"
+	"net"
+	"os"
+	"sync"
+	"time"
+)
+
+// managedConn is a bidirectional network connection that keeps its own
+// internal state and synchronization, buffering data sent and received.
+type managedConn struct {
+	mu           sync.Mutex
+	cond         *sync.Cond
+	deadline     *deadline
+	local        *byteBuffer
+	remote       *byteBuffer
+	localClosed  bool
+	remoteClosed bool
+}
+
+// newManagedConn returns a new managedConn instance, with the condition
+// variable initialized using the connection's own mutex.
+func newManagedConn() *managedConn {
+	conn := &managedConn{
+		deadline: newDeadline(),
+		local:    newByteBuffer(),
+		remote:   newByteBuffer(),
+	}
+	conn.cond = sync.NewCond(&conn.mu)
+	return conn
+}
+
+// Close closes the connection from the local side, stopping any active
+// deadline timers and notifying waiters.
+// If the connection is already closed, Close returns net.ErrClosed.
+func (c *managedConn) Close() error {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	if c.localClosed {
+		return net.ErrClosed
+	}
+	c.localClosed = true
+	c.deadline.stopLocked()
+	c.cond.Broadcast()
+	return nil
+}
+
+// Read reads data from the connection into p.
+// It returns an error if the connection is locally closed or if the read
+// deadline has expired. Zero length reads are allowed unconditionally.
+// If the remote side is closed and no data remains, Read returns io.EOF.
+func (c *managedConn) Read(p []byte) (int, error) {
+	if len(p) == 0 {
+		return 0, nil
+	}
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	for c.remote.len() == 0 && !c.remoteClosed {
+		if c.localClosed {
+			return 0, net.ErrClosed
+		}
+		if c.deadline.isExpiredLocked() {
+			return 0, os.ErrDeadlineExceeded
+		}
+		c.cond.Wait()
+	}
+	if c.remote.len() == 0 {
+		if c.localClosed {
+			return 0, net.ErrClosed
+		}
+		if c.remoteClosed {
+			return 0, io.EOF
+		}
+		return 0, os.ErrDeadlineExceeded
+	}
+	n := c.remote.read(p)
+	if n > 0 {
+		c.cond.Broadcast()
+	}
+	return n, nil
+}
+
+// Write writes data to the connection.
+// It returns an error if the connection is locally closed, if the write
+// deadline has expired, or if the remote side is closed.
+// Zero length writes are silently accepted.
+func (c *managedConn) Write(p []byte) (int, error) {
+	if len(p) == 0 {
+		return 0, nil
+	}
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	if c.localClosed {
+		return 0, net.ErrClosed
+	}
+	if c.deadline.isExpiredLocked() {
+		return 0, os.ErrDeadlineExceeded
+	}
+	if c.remoteClosed {
+		return 0, errors.New("resumption: write on closed connection")
+	}
+	n := c.local.write(p)
+	if n > 0 {
+		c.cond.Broadcast()
+	}
+	return n, nil
+}
+
+// LocalAddr returns the local address of the connection.
+func (c *managedConn) LocalAddr() net.Addr {
+	return nil
+}
+
+// RemoteAddr returns the remote address of the connection.
+func (c *managedConn) RemoteAddr() net.Addr {
+	return nil
+}
+
+// SetDeadline sets the read and write deadline.
+// A zero value for t means the deadline is disabled.
+func (c *managedConn) SetDeadline(t time.Time) error {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	c.deadline.setLocked(t)
+	return nil
+}
+
+// SetReadDeadline sets the read deadline.
+// A zero value for t means the deadline is disabled.
+func (c *managedConn) SetReadDeadline(t time.Time) error {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	c.deadline.setLocked(t)
+	return nil
+}
+
+// SetWriteDeadline sets the write deadline.
+// A zero value for t means the deadline is disabled.
+func (c *managedConn) SetWriteDeadline(t time.Time) error {
+	c.mu.Lock()
+	defer c.mu.Unlock()
+	c.deadline.setLocked(t)
+	return nil
+}
+
+// deadline manages a single deadline, with synchronized access and a
+// reusable timer that triggers the timeout and notifies waiters.
+type deadline struct {
+	mu      sync.Mutex
+	timer   *time.Timer
+	timeout bool
+	stopped bool
+	cond    *sync.Cond
+}
+
+// newDeadline returns a new, stopped deadline.
+func newDeadline() *deadline {
+	d := &deadline{
+		stopped: true,
+	}
+	d.cond = sync.NewCond(&d.mu)
+	return d
+}
+
+// isExpiredLocked returns true if the deadline has expired.
+// The caller must hold the managedConn mutex.
+func (d *deadline) isExpiredLocked() bool {
+	d.mu.Lock()
+	defer d.mu.Unlock()
+	return d.timeout
+}
+
+// stopLocked stops the deadline, if active.
+// The caller must hold the managedConn mutex.
+func (d *deadline) stopLocked() {
+	d.setLocked(time.Time{})
+}
+
+// setLocked sets the deadline to t, stopping any existing timer first.
+// A zero value for t disables the deadline (the stopped state).
+// The caller must hold the managedConn mutex.
+func (d *deadline) setLocked(t time.Time) {
+	d.setDeadlineLocked(t, time.Now())
+}
+
+// setDeadlineLocked sets the deadline to t, using now as the current time.
+// It stops any existing timer, waiting for it to fire if necessary.
+// If t is in the past, the timeout flag is set immediately.
+func (d *deadline) setDeadlineLocked(t time.Time, now time.Time) {
+	if d.timer != nil {
+		if !d.timer.Stop() {
+			// The timer has already fired, drain it.
+			select {
+			case <-d.timer.C:
+			default:
+			}
+		}
+		d.timer = nil
+	}
+	d.stopped = true
+	d.timeout = false
+	if t.IsZero() {
+		return
+	}
+	if !t.After(now) {
+		d.timeout = true
+		d.cond.Broadcast()
+		return
+	}
+	d.stopped = false
+	d.timer = time.NewTimer(t.Sub(now))
+	go func() {
+		<-d.timer.C
+		d.mu.Lock()
+		d.timeout = true
+		d.stopped = true
+		d.cond.Broadcast()
+		d.mu.Unlock()
+	}()
+}

