+// maxClientCertPoolSize is the maximum size of the client certificate pool
+// (i.e. the list of acceptable CAs advertised to a TLS client during the
+// handshake). Per https://tools.ietf.org/html/rfc5246#section-7.4.4 the total
+// size of the CA subjects sent to the client can't exceed 2^16-1 (due to the
+// 2-byte length encoding). The crypto/tls stack will panic if this limit is
+// exceeded, so we must never advertise a pool larger than this.
+const maxClientCertPoolSize = math.MaxUint16
+
+// clientCertPoolSize returns the size the pool would occupy in a TLS
+// handshake: each subject is preceded by a 2-byte length prefix.
+func clientCertPoolSize(pool *x509.CertPool) int64 {
+	var size int64
+	for _, s := range pool.Subjects() {
+		size += 2
+		size += int64(len(s))
+	}
+	return size
+}
+
