+// ReadAtMost reads from the provided reader up to the specified limit
+// in bytes, returning the data read and an error if any. If the limit
+// is reached before the end of the content, ErrLimitReached is returned
+// along with the bytes read up to that point.
+func ReadAtMost(r io.Reader, limit int64) ([]byte, error) {
+	out, err := io.ReadAll(io.LimitReader(r, limit))
+	if err != nil {
+		return nil, trace.Wrap(err)
