+// MaskKeyName masks the supplied key name by replacing the first 75% of its
+// bytes with '*' and returns the masked value as a byte slice. The original
+// length is preserved so the last 25% of the key remains visible.
+func MaskKeyName(keyName string) []byte {
+	keyNameBytes := []byte(keyName)
+	hiddenBefore := int(math.Floor(0.75 * float64(len(keyNameBytes))))
+	asterisks := bytes.Repeat([]byte("*"), hiddenBefore)
+	return append(asterisks, keyNameBytes[hiddenBefore:]...)
+}
