+// AsyncEmitterConfig provides parameters for async emitter
+type AsyncEmitterConfig struct {
+	// Inner is the emitter to wrap
+	Inner Emitter
+	// BufferSize is the size of the event buffer,
+	// defaults to defaults.AsyncBufferSize when zero
+	BufferSize int
+}
+
+// CheckAndSetDefaults checks and sets default values
+func (c *AsyncEmitterConfig) CheckAndSetDefaults() error {
+	if c.Inner == nil {
+		return trace.BadParameter("missing parameter Inner")
+	}
+	if c.BufferSize <= 0 {
+		c.BufferSize = defaults.AsyncBufferSize
+	}
+	return nil
+}
+
+// NewAsyncEmitter returns a new instance of async emitter
+func NewAsyncEmitter(cfg AsyncEmitterConfig) (*AsyncEmitter, error) {
+	if err := cfg.CheckAndSetDefaults(); err != nil {
+		return nil, trace.Wrap(err)
+	}
+	ctx, cancel := context.WithCancel(context.Background())
+	emitter := &AsyncEmitter{
+		AsyncEmitterConfig: cfg,
+		ctx:                ctx,
+		cancel:             cancel,
+		eventsCh:           make(chan AuditEvent, cfg.BufferSize),
+		closed:             atomic.NewBool(false),
+	}
+	emitter.wg.Add(1)
+	go emitter.processEvents()
+	return emitter, nil
+}
+
+// AsyncEmitter is an emitter that sends events to the inner
+// emitter asynchronously, it never blocks the caller and
+// drops events when the buffer is full
+type AsyncEmitter struct {
+	AsyncEmitterConfig
+	ctx      context.Context
+	cancel   context.CancelFunc
+	eventsCh chan AuditEvent
+	closed   *atomic.Bool
+	wg       sync.WaitGroup
+}
+
+// Close closes the emitter, cancels the background processing
+// and prevents further submissions
+func (e *AsyncEmitter) Close() error {
+	if !e.closed.CAS(false, true) {
+		return nil
+	}
+	e.cancel()
+	e.wg.Wait()
+	return nil
+}
+
+// EmitAuditEvent emits audit event asynchronously,
+// it never blocks, events are dropped when the buffer is full
+func (e *AsyncEmitter) EmitAuditEvent(ctx context.Context, event AuditEvent) error {
+	if e.closed.Load() {
+		return trace.ConnectionProblem(nil, "emitter has been closed")
+	}
+	select {
+	case e.eventsCh <- event:
+		return nil
+	default:
+		// buffer is full, drop the event
+		log.WithError(trace.ConnectionProblem(nil, "buffer is full")).
+			WithField("event", event.GetType()).
+			Errorf("Failed to enqueue audit event, dropping it.")
+		return trace.ConnectionProblem(nil, "buffer is full, dropping event")
+	}
+}
+
+// processEvents forwards events from the buffer to the inner emitter
+func (e *AsyncEmitter) processEvents() {
+	defer e.wg.Done()
+	for {
+		select {
+		case event := <-e.eventsCh:
+			if err := e.Inner.EmitAuditEvent(e.ctx, event); err != nil {
+				log.WithError(err).Errorf("Failed to emit audit event.")
+			}
+		case <-e.ctx.Done():
+			return
+		}
+	}
+}
