+++ b/utils/cache/simple_cache.go
@@ -0,0 +1,68 @@
+package cache
+
+import (
+	"time"
+
+	"github.com/jellydator/ttlcache/v2"
+)
+
+// SimpleCache is a generic, strongly typed cache interface that provides common
+// cache operations: adding values, adding values with an explicit TTL,
+// retrieving values, retrieving values with a loader on cache miss, and
+// listing the active keys.
+type SimpleCache[V any] interface {
+	// Add inserts a value under the given key using the cache's default TTL.
+	Add(key string, value V) error
+	// AddWithTTL inserts a value under the given key with the given expiration time.
+	AddWithTTL(key string, value V, ttl time.Duration) error
+	// Get returns the value associated with the key if it exists and has not expired.
+	// It returns the zero value of V and a non-nil error if the key is missing or expired.
+	Get(key string) (V, error)
+	// GetWithLoader returns the cached value if present. If the key is missing, it invokes
+	// the loader, stores the returned value with the provided TTL, and returns that value.
+	// If the loader returns an error, that error is propagated without storing a value.
+	GetWithLoader(key string, loader func(key string) (V, time.Duration, error)) (V, error)
+	// Keys returns a list of all active (non-expired) keys currently stored in the cache.
+	Keys() []string
+}
+
+// NewSimpleCache returns a new strongly typed cache instance implementing SimpleCache[V].
+func NewSimpleCache[V any]() SimpleCache[V] {
+	return &simpleCacheImpl[V]{cache: ttlcache.NewCache()}
+}
+
+type simpleCacheImpl[V any] struct {
+	cache *ttlcache.Cache
+}
+
+func (c *simpleCacheImpl[V]) Add(key string, value V) error {
+	return c.cache.Set(key, value)
+}
+
+func (c *simpleCacheImpl[V]) AddWithTTL(key string, value V, ttl time.Duration) error {
+	return c.cache.SetWithTTL(key, value, ttl)
+}
+
+func (c *simpleCacheImpl[V]) Get(key string) (V, error) {
+	var zero V
+	v, err := c.cache.Get(key)
+	if err != nil {
+		return zero, err
+	}
+	return v.(V), nil
+}
+
+func (c *simpleCacheImpl[V]) GetWithLoader(key string, loader func(key string) (V, time.Duration, error)) (V, error) {
+	var zero V
+	v, err := c.cache.GetByLoader(key, func(key string) (interface{}, time.Duration, error) {
+		return loader(key)
+	})
+	if err != nil {
+		return zero, err
+	}
+	return v.(V), nil
+}
+
+func (c *simpleCacheImpl[V]) Keys() []string {
+	return c.cache.GetKeys()
+}

