+package criteria
+
+import (
+	"encoding/json"
+
+	"github.com/Masterminds/squirrel"
+)
+
+// Criteria is a structure that encapsulates logical expressions with pagination parameters
+type Criteria struct {
+	Expression squirrel.Sqlizer
+	Sort       string
+	Order      string
+	Max        int
+	Offset     int
+}
+
+// ToSql converts the internal expression to SQL with arguments
+func (c Criteria) ToSql() (sql string, args []interface{}, err error) {
+	return c.Expression.ToSql()
+}
+
+// MarshalJSON serializes the Criteria structure to JSON format
+func (c Criteria) MarshalJSON() ([]byte, error) {
+	out := map[string]interface{}{}
+	if c.Sort != "" {
+		out["sort"] = c.Sort
+	}
+	if c.Order != "" {
+		out["order"] = c.Order
+	}
+	if c.Max != 0 {
+		out["max"] = c.Max
+	}
+	if c.Offset != 0 {
+		out["offset"] = c.Offset
+	}
+	if c.Expression != nil {
+		expr, err := marshalExpression(c.Expression)
+		if err != nil {
+			return nil, err
+		}
+		for k, v := range expr {
+			out[k] = v
+		}
+	}
+	return json.Marshal(out)
+}
+
+// UnmarshalJSON deserializes the Criteria from JSON preserving structure
+func (c *Criteria) UnmarshalJSON(data []byte) error {
+	var m map[string]interface{}
+	if err := json.Unmarshal(data, &m); err != nil {
+		return err
+	}
+	if sort, ok := m["sort"].(string); ok {
+		c.Sort = sort
+	}
+	if order, ok := m["order"].(string); ok {
+		c.Order = order
+	}
+	if max, ok := m["max"].(float64); ok {
+		c.Max = int(max)
+	}
+	if offset, ok := m["offset"].(float64); ok {
+		c.Offset = int(offset)
+	}
+	expr, err := unmarshalExpression(m)
+	if err != nil {
+		return err
+	}
+	c.Expression = expr
+	return nil
+}
