@@ -0,0 +1,252 @@
+package criteria
+
+import (
+	"errors"
+	"fmt"
+	"reflect"
+
+	"github.com/Masterminds/squirrel"
+)
+
+// marshalExpression converts a Sqlizer expression to a JSON-serializable map
+func marshalExpression(expr squirrel.Sqlizer) (map[string]interface{}, error) {
+	switch e := expr.(type) {
+	case All:
+		items := make([]interface{}, len(e))
+		for i, it := range e {
+			m, err := marshalExpression(it)
+			if err != nil {
+				return nil, err
+			}
+			items[i] = m
+		}
+		return map[string]interface{}{"all": items}, nil
+	case Any:
+		items := make([]interface{}, len(e))
+		for i, it := range e {
+			m, err := marshalExpression(it)
+			if err != nil {
+				return nil, err
+			}
+			items[i] = m
+		}
+		return map[string]interface{}{"any": items}, nil
+	case Is:
+		return marshalSingleValue(e, "is")
+	case IsNot:
+		return marshalSingleValue(e, "isNot")
+	case Gt:
+		return marshalSingleValue(e, "gt")
+	case Lt:
+		return marshalSingleValue(e, "lt")
+	case Before:
+		return marshalSingleValue(squirrel.Lt(e), "before")
+	case After:
+		return marshalSingleValue(squirrel.Gt(e), "after")
+	case Contains:
+		return marshalSingleValue(e, "contains")
+	case NotContains:
+		return marshalSingleValue(e, "notContains")
+	case StartsWith:
+		return marshalSingleValue(e, "startsWith")
+	case EndsWith:
+		return marshalSingleValue(e, "endsWith")
+	case InTheRange:
+		return marshalField(e.Field, map[string]interface{}{"inTheRange": []interface{}{e.From, e.To}})
+	case InTheLast:
+		return marshalField(e.Field, map[string]interface{}{"inTheLast": e.Days})
+	case NotInTheLast:
+		return marshalField(e.Field, map[string]interface{}{"notInTheLast": e.Days})
+	default:
+		return nil, errors.New("unsupported expression type: " + reflect.TypeOf(expr).String())
+	}
+}
+
+func marshalField(field string, inner map[string]interface{}) (map[string]interface{}, error) {
+	out := map[string]interface{}{}
+	for k, v := range inner {
+		out[k] = map[string]interface{}{field: v}
+	}
+	return out, nil
+}
+
+func marshalSingleValue(m map[string]interface{}, key string) (map[string]interface{}, error) {
+	out := map[string]interface{}{}
+	for k, v := range m {
+		out[key] = map[string]interface{}{k: v}
+	}
+	return out, nil
+}
+
+// unmarshalExpression reconstructs a Sqlizer expression from a JSON map
+func unmarshalExpression(m map[string]interface{}) (squirrel.Sqlizer, error) {
+	for key, val := range m {
+		switch key {
+		case "all":
+			items, ok := val.([]interface{})
+			if !ok {
+				return nil, errors.New("'all' must be a list")
+			}
+			all := make(All, len(items))
+			for i, it := range items {
+				expr, err := unmarshalExpression(it.(map[string]interface{}))
+				if err != nil {
+					return nil, err
+				}
+				all[i] = expr
+			}
+			return all, nil
+		case "any":
+			items, ok := val.([]interface{})
+			if !ok {
+				return nil, errors.New("'any' must be a list")
+			}
+			any := make(Any, len(items))
+			for i, it := range items {
+				expr, err := unmarshalExpression(it.(map[string]interface{}))
+				if err != nil {
+					return nil, err
+				}
+				any[i] = expr
+			}
+			return any, nil
+		case "is":
+			return unmarshalSingleValue(val, &Is{})
+		case "isNot":
+			return unmarshalSingleValue(val, &IsNot{})
+		case "gt":
+			return unmarshalSingleValue(val, &Gt{})
+		case "lt":
+			return unmarshalSingleValue(val, &Lt{})
+		case "before":
+			return unmarshalSingleValue(val, &Before{})
+		case "after":
+			return unmarshalSingleValue(val, &After{})
+		case "contains":
+			return unmarshalSingleValue(val, &Contains{})
+		case "notContains":
+			return unmarshalSingleValue(val, &NotContains{})
+		case "startsWith":
+			return unmarshalSingleValue(val, &StartsWith{})
+		case "endsWith":
+			return unmarshalSingleValue(val, &EndsWith{})
+		case "inTheRange":
+			field, items, err := unmarshalFieldValue(val)
+			if err != nil {
+				return nil, err
+			}
+			if len(items) != 2 {
+				return nil, errors.New("'inTheRange' must have 2 elements")
+			}
+			return InTheRange{Field: field, From: items[0], To: items[1]}, nil
+		case "inTheLast":
+			field, days, err := unmarshalFieldInt(val)
+			if err != nil {
+				return nil, err
+			}
+			return InTheLast{Field: field, Days: days}, nil
+		case "notInTheLast":
+			field, days, err := unmarshalFieldInt(val)
+			if err != nil {
+				return nil, err
+			}
+			return NotInTheLast{Field: field, Days: days}, nil
+		case "sort", "order", "max", "offset":
+			// pagination fields, skip
+		default:
+			return nil, fmt.Errorf("unknown criteria key: %s", key)
+		}
+	}
+	return nil, errors.New("no criteria expression found")
+}
+
+func unmarshalSingleValue(val interface{}, m squirrel.Sqlizer) (squirrel.Sqlizer, error) {
+	mm, ok := val.(map[string]interface{})
+	if !ok {
+		return nil, errors.New("expected a field/value object")
+	}
+	switch out := m.(type) {
+	case *Is:
+		for k, v := range mm {
+			(*out)[k] = v
+		}
+		return m, nil
+	case *IsNot:
+		for k, v := range mm {
+			(*out)[k] = v
+		}
+		return m, nil
+	case *Gt:
+		for k, v := range mm {
+			(*out)[k] = v
+		}
+		return m, nil
+	case *Lt:
+		for k, v := range mm {
+			(*out)[k] = v
+		}
+		return m, nil
+	case *Before:
+		for k, v := range mm {
+			(*out)[k] = v
+		}
+		return m, nil
+	case *After:
+		for k, v := range mm {
+			(*out)[k] = v
+		}
+		return m, nil
+	case *Contains:
+		for k, v := range mm {
+			(*out)[k] = v
+		}
+		return m, nil
+	case *NotContains:
+		for k, v := range mm {
+			(*out)[k] = v
+		}
+		return m, nil
+	case *StartsWith:
+		for k, v := range mm {
+			(*out)[k] = v
+		}
+		return m, nil
+	case *EndsWith:
+		for k, v := range mm {
+			(*out)[k] = v
+		}
+		return m, nil
+	default:
+		return nil, errors.New("unsupported single value operator")
+	}
+}
+
+func unmarshalFieldValue(val interface{}) (string, []interface{}, error) {
+	mm, ok := val.(map[string]interface{})
+	if !ok {
+		return "", nil, errors.New("expected a field/value object")
+	}
+	for field, v := range mm {
+		items, ok := v.([]interface{})
+		if !ok {
+			return "", nil, errors.New("expected a list value")
+		}
+		return field, items, nil
+	}
+	return "", nil, errors.New("expected a field/value object")
+}
+
+func unmarshalFieldInt(val interface{}) (string, int, error) {
+	mm, ok := val.(map[string]interface{})
+	if !ok {
+		return "", 0, errors.New("expected a field/value object")
+	}
+	for field, v := range mm {
+		days, ok := v.(float64)
+		if !ok {
+			return "", 0, errors.New("expected a numeric value")
+		}
+		return field, int(days), nil
+	}
+	return "", 0, errors.New("expected a field/value object")
+}
