+package criteria
+
+import (
+	"fmt"
+	"time"
+
+	"github.com/Masterminds/squirrel"
+)
+
+// All is a logical conjunction (AND) of conditions. It is an alias of squirrel.And,
+// generating SQL with parentheses for logical grouping.
+type All squirrel.And
+
+// ToSql generates SQL with AND between conditions
+func (a All) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.And(a).ToSql()
+}
+
+// Any is a logical disjunction (OR) of conditions. It is an alias of squirrel.Or,
+// generating SQL with parentheses for logical grouping.
+type Any squirrel.Or
+
+// ToSql generates SQL with OR between conditions
+func (a Any) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Or(a).ToSql()
+}
+
+// Is is the exact equality operator
+type Is squirrel.Eq
+
+// ToSql generates equality SQL with placeholders using fieldMap
+func (i Is) ToSql() (sql string, args []interface{}, err error) {
+	return mapToDbField(squirrel.Eq(i)).ToSql()
+}
+
+// IsNot is the exact inequality operator
+type IsNot squirrel.NotEq
+
+// ToSql generates inequality SQL with placeholders using fieldMap
+func (i IsNot) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.NotEq(mapToDbField(squirrel.Eq(i))).ToSql()
+}
+
+// Gt is the greater than operator
+type Gt squirrel.Gt
+
+// ToSql generates greater than SQL with placeholders using fieldMap
+func (g Gt) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Gt(mapToDbField(squirrel.Eq(g))).ToSql()
+}
+
+// Lt is the less than operator
+type Lt squirrel.Lt
+
+// ToSql generates less than SQL with placeholders using fieldMap
+func (l Lt) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Lt(mapToDbField(squirrel.Eq(l))).ToSql()
+}
+
+// Before is the date before operator
+type Before squirrel.Lt
+
+// ToSql generates less than SQL for dates using fieldMap
+func (b Before) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Lt(mapToDbField(squirrel.Eq(squirrel.Lt(b)))).ToSql()
+}
+
+// After is the date after operator
+type After squirrel.Gt
+
+// ToSql generates greater than SQL for dates using fieldMap
+func (a After) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.Gt(mapToDbField(squirrel.Eq(squirrel.Gt(a)))).ToSql()
+}
+
+// Contains is the text search operator with %value% pattern
+type Contains squirrel.ILike
+
+// ToSql generates ILIKE SQL with wrapping pattern using fieldMap
+func (c Contains) ToSql() (sql string, args []interface{}, err error) {
+	m := squirrel.ILike{}
+	for k, v := range c {
+		m[mapField(k)] = fmt.Sprintf("%%%s%%", v)
+	}
+	return m.ToSql()
+}
+
+// NotContains is the text exclusion operator with %value% pattern
+type NotContains squirrel.NotILike
+
+// ToSql generates NOT ILIKE SQL with wrapping pattern using fieldMap
+func (c NotContains) ToSql() (sql string, args []interface{}, err error) {
+	m := squirrel.NotILike{}
+	for k, v := range c {
+		m[mapField(k)] = fmt.Sprintf("%%%s%%", v)
+	}
+	return m.ToSql()
+}
+
+// StartsWith is the prefix search operator with value% pattern
+type StartsWith squirrel.ILike
+
+// ToSql generates ILIKE SQL with prefix pattern using fieldMap
+func (s StartsWith) ToSql() (sql string, args []interface{}, err error) {
+	m := squirrel.ILike{}
+	for k, v := range s {
+		m[mapField(k)] = fmt.Sprintf("%s%%", v)
+	}
+	return m.ToSql()
+}
+
+// EndsWith is the suffix search operator with %value pattern
+type EndsWith squirrel.ILike
+
+// ToSql generates ILIKE SQL with suffix pattern using fieldMap
+func (e EndsWith) ToSql() (sql string, args []interface{}, err error) {
+	m := squirrel.ILike{}
+	for k, v := range e {
+		m[mapField(k)] = fmt.Sprintf("%%%s", v)
+	}
+	return m.ToSql()
+}
+
+// InTheRange is the numeric or date range operator using >= and <=
+type InTheRange struct {
+	Field string
+	From  interface{}
+	To    interface{}
+}
+
+// ToSql generates SQL with >= and <= conditions using fieldMap
+func (r InTheRange) ToSql() (sql string, args []interface{}, err error) {
+	return squirrel.And{
+		squirrel.GtOrEq{mapField(r.Field): r.From},
+		squirrel.LtOrEq{mapField(r.Field): r.To},
+	}.ToSql()
+}
+
+// InTheLast is the operator for dates within the last N days
+type InTheLast struct {
+	Field string
+	Days  int
+}
+
+// ToSql generates greater than calculated date SQL using fieldMap
+func (i InTheLast) ToSql() (sql string, args []interface{}, err error) {
+	period := time.Now().Add(time.Duration(-24*i.Days) * time.Hour)
+	return squirrel.Gt{mapField(i.Field): period}.ToSql()
+}
+
+// NotInTheLast is the operator for dates NOT within the last N days
+type NotInTheLast struct {
+	Field string
+	Days  int
+}
+
+// ToSql generates SQL with OR of less than calculated date or IS NULL using fieldMap
+func (i NotInTheLast) ToSql() (sql string, args []interface{}, err error) {
+	period := time.Now().Add(time.Duration(-24*i.Days) * time.Hour)
+	return squirrel.Or{
+		squirrel.Lt{mapField(i.Field): period},
+		squirrel.Eq{mapField(i.Field): nil},
+	}.ToSql()
+}
+
+// mapField translates an interface field name to a fully qualified SQL column
+func mapField(field string) string {
+	if dbField, ok := fieldMap[field]; ok {
+		return dbField
+	}
+	return field
+}
+
+// mapToDbField translates the keys of the given expression to SQL columns
+func mapToDbField(m squirrel.Eq) squirrel.Eq {
+	eq := squirrel.Eq{}
+	for k, v := range m {
+		eq[mapField(k)] = v
+	}
+	return eq
+}

