+	Short: "Delete old backups, keeping only the latest backup.count",
+	Run: func(cmd *cobra.Command, args []string) {
+		preRun()
+		defer db.Init()()
+		if conf.Server.Backup.Count == 0 && !backupForce {
+			if !confirm("backup.count is 0, all backups will be deleted. Are you sure?") {
+				log.Info("Aborting")
+				return
+			}
+		}
+		pruned, err := db.Db().Prune(cmd.Context())
+		if err != nil {
+			log.Fatal("Error pruning backups", err)
+		}
+		log.Info("Pruned backups", "count", pruned)
+	},
+}
+
+var backupRestoreCmd = &cobra.Command{
+	Use:   "restore",
+	Short: "Restore the database from a backup file",
+	Run: func(cmd *cobra.Command, args []string) {
+		preRun()
+		if backupFile == "" {
+			log.Fatal("You must specify the backup file with --backup-file")
+		}
+		if !backupForce {
+			if !confirm("This will REPLACE the current database with the backup. Are you sure?") {
+				log.Info("Aborting")
+				return
+			}
+		}
+		defer db.Init()()
+		err := db.Db().Restore(cmd.Context(), backupFile)
