+		}
+		log.Info("Database restored", "path", backupFile)
+	},
+}
+
+// confirm asks the user a yes/no question on the terminal, returning true for yes.
+func confirm(question string) bool {
+	fmt.Print(question + " [y/N] ")
+	reader := bufio.NewReader(os.Stdin)
+	answer, _ := reader.ReadString('\n')
+	answer = strings.ToLower(strings.TrimSpace(answer))
+	return answer == "y" || answer == "yes"
+}
+
+// schedulePeriodicBackup schedules periodic database backups and pruning, if configured.
+func schedulePeriodicBackup(ctx context.Context) func() error {
+	return func() error {
+		backupPath := conf.Server.Backup.Path
+		schedule := conf.Server.Backup.Schedule
+		count := conf.Server.Backup.Count
+		if backupPath == "" || schedule == "" || count == 0 {
+			log.Debug("Automatic backups are DISABLED")
+			return nil
+		}
+
+		schedulerInstance := scheduler.GetInstance()
+		log.Info("Scheduling periodic backups", "schedule", schedule, "count", count)
+		err := schedulerInstance.Add(schedule, func() {
+			if _, err := db.Db().Backup(context.Background()); err != nil {
+				log.Error("Error creating backup", err)
+				return
+			}
+			if _, err := db.Db().Prune(context.Background()); err != nil {
+				log.Error("Error pruning backups", err)
+			}
+		})
+		if err != nil {
+			log.Error("Error scheduling periodic backup", err)
+		}
+		return nil
+	}
+}
