+	rootCmd.PersistentFlags().String("backup.path", viper.GetString("backup.path"), "folder to store database backups")
+	rootCmd.PersistentFlags().String("backup.schedule", viper.GetString("backup.schedule"), "schedule for automatic backups (duration or cron expression)")
+	rootCmd.PersistentFlags().Int("backup.count", viper.GetInt("backup.count"), "number of backups to keep")
+
+	_ = viper.BindPFlag("backup.path", rootCmd.PersistentFlags().Lookup("backup.path"))
+	_ = viper.BindPFlag("backup.schedule", rootCmd.PersistentFlags().Lookup("backup.schedule"))
+	_ = viper.BindPFlag("backup.count", rootCmd.PersistentFlags().Lookup("backup.count"))
+}
