--- /dev/null
+++ b/db/backup.go
@@ -0,0 +1,123 @@
+package db
+
+import (
+	"context"
+	"fmt"
+	"os"
+	"path/filepath"
+	"regexp"
+	"sort"
+	"time"
+
+	"github.com/navidrome/navidrome/conf"
+	"github.com/navidrome/navidrome/log"
+)
+
+const backupFileFormat = "navidrome_backup_%s.db"
+
+var backupFileNameRegexp = regexp.MustCompile(`^navidrome_backup_(\d{8}_\d{6})\.db$`)
+
+// backupFileName returns the name of a backup file for the given timestamp,
+// e.g. navidrome_backup_20240101_123000.db
+func backupFileName(ts time.Time) string {
+	return fmt.Sprintf(backupFileFormat, ts.Format("20060102_150405"))
+}
+
+// backupTimestamp extracts the timestamp encoded in a backup file name,
+// returning false if the name does not match the expected format.
+func backupTimestamp(name string) (time.Time, bool) {
+	matches := backupFileNameRegexp.FindStringSubmatch(name)
+	if matches == nil {
+		return time.Time{}, false
+	}
+	ts, err := time.Parse("20060102_150405", matches[1])
+	if err != nil {
+		return time.Time{}, false
+	}
+	return ts, true
+}
+
+func (d *db) Backup(_ context.Context) (string, error) {
+	if conf.Server.Backup.Path == "" {
+		return "", fmt.Errorf("backup path is not configured")
+	}
+	if err := os.MkdirAll(conf.Server.Backup.Path, os.ModePerm); err != nil {
+		return "", fmt.Errorf("creating backup path: %w", err)
+	}
+	backupFile := filepath.Join(conf.Server.Backup.Path, backupFileName(time.Now()))
+	err := d.WriteDB().Ping()
+	if err != nil {
+		return "", err
+	}
+	// Use the SQLite online backup API to copy the live database to the backup file
+	_, err = d.WriteDB().Exec(fmt.Sprintf("VACUUM INTO '%s'", backupFile))
+	if err != nil {
+		return "", fmt.Errorf("backing up database: %w", err)
+	}
+	log.Info("Created database backup", "path", backupFile)
+	return backupFile, nil
+}
+
+func (d *db) Prune(_ context.Context) (int, error) {
+	return prune()
+}
+
+// prune deletes old backup files, keeping only the most recent
+// conf.Server.Backup.Count backups. It returns the number of deleted files.
+func prune() (int, error) {
+	backupPath := conf.Server.Backup.Path
+	if backupPath == "" {
+		return 0, fmt.Errorf("backup path is not configured")
+	}
+	entries, err := os.ReadDir(backupPath)
+	if err != nil {
+		return 0, fmt.Errorf("reading backup path: %w", err)
+	}
+	type backupFile struct {
+		name string
+		ts   time.Time
+	}
+	var backups []backupFile
+	for _, entry := range entries {
+		if entry.IsDir() {
+			continue
+		}
+		if ts, ok := backupTimestamp(entry.Name()); ok {
+			backups = append(backups, backupFile{name: entry.Name(), ts: ts})
+		}
+	}
+	// Sort by descending timestamp so the most recent backups come first
+	sort.Slice(backups, func(i, j int) bool {
+		return backups[i].ts.After(backups[j].ts)
+	})
+	count := conf.Server.Backup.Count
+	if count < 0 {
+		count = 0
+	}
+	pruned := 0
+	for _, backup := range backups[count:] {
+		filePath := filepath.Join(backupPath, backup.name)
+		if err := os.Remove(filePath); err != nil {
+			if os.IsNotExist(err) {
+				continue
+			}
+			return pruned, fmt.Errorf("deleting backup file %s: %w", filePath, err)
+		}
+		log.Info("Pruned backup file", "path", filePath)
+		pruned++
+	}
+	return pruned, nil
+}
+
+func (d *db) Restore(_ context.Context, path string) error {
+	if _, err := os.Stat(path); err != nil {
+		return fmt.Errorf("backup file not found: %w", err)
+	}
+	// Replace the live database with the contents of the backup file
+	_, err := d.WriteDB().Exec(fmt.Sprintf("ATTACH DATABASE '%s' AS backup; VACUUM INTO '%s'", path, Path))
+	if err != nil {
+		return fmt.Errorf("restoring database from %s: %w", path, err)
+	}
+	log.Info("Restored database from backup", "path", path)
+	return nil
+}
