+import { useMemo } from 'react';
+
+import { c } from 'ttag';
+
+import { FeatureCode, useFeature } from '@proton/components';
+import { Recipient } from '@proton/shared/lib/interfaces';
+
+import { useEncryptedSearchContext } from '../../containers/EncryptedSearchProvider';
+import { isProtonSender } from '../../helpers/elements';
+import { getElementSenders } from '../../helpers/recipients';
+import { useRecipientLabel } from '../../hooks/contact/useRecipientLabel';
+import { RecipientOrGroup } from '../../models/address';
+import { Element } from '../../models/element';
+import ItemAction from './ItemAction';
+import ItemUnread from './ItemUnread';
+import ProtonBadgeType, { PROTON_BADGE_TYPE } from './ProtonBadgeType';
+
+interface Props {
+    element: Element;
+    conversationMode: boolean;
+    loading: boolean;
+    unread: boolean;
+    displayRecipients: boolean;
+    isSelected: boolean;
+    labelID?: string;
+    className?: string;
+    unreadClassName?: string;
+    actionClassName?: string;
+    addressClassName?: string;
+}
+
+const ItemSenders = ({
+    element,
+    conversationMode,
+    loading,
+    unread,
+    displayRecipients,
+    isSelected,
+    labelID,
+    className = '',
+    unreadClassName = '',
+    actionClassName = '',
+    addressClassName = '',
+}: Props) => {
+    const { shouldHighlight, highlightMetadata } = useEncryptedSearchContext();
+    const { getRecipientLabel, getRecipientsOrGroups } = useRecipientLabel();
+    const { feature: protonBadgeFeature } = useFeature(FeatureCode.ProtonBadge);
+
+    const recipients: Recipient[] = useMemo(
+        () => getElementSenders(element, conversationMode, displayRecipients),
+        [element, conversationMode, displayRecipients]
+    );
+    const recipientsOrGroup = getRecipientsOrGroups(recipients);
+    const [firstRecipientOrGroup] = recipientsOrGroup;
+    const sendersLabels = useMemo(
+        () => recipients.map((recipient) => getRecipientLabel(recipient, true)),
+        [recipients]
+    );
+    const sendersAddresses = useMemo(() => recipients.map((recipient) => recipient?.Address), [recipients]);
+
+    const highlightData = shouldHighlight();
+    const senders = sendersLabels.join(', ');
+    const addresses = sendersAddresses.join(', ');
+
+    const sendersContent = useMemo(
+        () =>
+            !loading && displayRecipients && !senders
+                ? c('Info').t`(No Recipient)`
+                : highlightData
+                ? highlightMetadata(senders, unread, true).resultJSX
+                : senders,
+        [loading, displayRecipients, senders, highlightData, highlightMetadata, unread]
+    );
+
+    const badgeType =
+        isProtonSender(element, (firstRecipientOrGroup || {}) as RecipientOrGroup, displayRecipients) &&
+        protonBadgeFeature?.Value
+            ? PROTON_BADGE_TYPE.VERIFIED
+            : undefined;
+
+    return (
+        <div className={className}>
+            <ItemUnread element={element} labelID={labelID || ''} className={unreadClassName} isSelected={isSelected} />
+            <ItemAction element={element} className={actionClassName} />
+            <span className={addressClassName} title={addresses} data-testid="message-row:sender-address">
+                {sendersContent}
+            </span>
+            {badgeType && <ProtonBadgeType badgeType={badgeType} selected={isSelected} />}
+        </div>
+    );
+};
