+import { Recipient } from '@proton/shared/lib/interfaces';
+import { Message } from '@proton/shared/lib/interfaces/mail/Message';
+import { getRecipients as getMessageRecipients, getSender } from '@proton/shared/lib/mail/messages';
+
+import { getRecipients as getConversationRecipients, getSenders as getConversationSenders } from './conversation';
+import { isMessage } from './elements';
+import { Element } from '../models/element';
+
+/**
+ * Get the senders/recipients to display for an element in a mail list.
+ * In conversation mode, returns the conversation senders.
+ * When displayRecipients is true, returns the recipients instead of the senders.
+ */
+export const getElementSenders = (element: Element, conversationMode: boolean, displayRecipients: boolean): Recipient[] => {
+    if (conversationMode) {
+        return displayRecipients ? getConversationRecipients(element) : getConversationSenders(element);
+    }
+
+    const message = isMessage(element) ? (element as Message) : undefined;
+    if (displayRecipients) {
+        return getMessageRecipients(message);
+    }
+
+    const sender = getSender(message);
+    return sender ? [sender] : [];
+};

