+++ b/packages/components/components/dropdown/utils.ts
@@ -0,0 +1,66 @@
+export type Unit = string;
+
+export enum DropdownSizeUnit {
+    Viewport = 'viewport',
+    Static = 'static',
+    Dynamic = 'dynamic',
+    Anchor = 'anchor',
+}
+
+export interface DropdownSize {
+    width?: DropdownSizeUnit | Unit;
+    height?: DropdownSizeUnit | Unit;
+    maxWidth?: DropdownSizeUnit | Unit;
+    maxHeight?: DropdownSizeUnit | Unit;
+}
+
+export const isUnit = (value: DropdownSizeUnit | Unit): boolean =>
+    Object.values(DropdownSizeUnit).includes(value as DropdownSizeUnit);
+
+export const getMaxSizeValue = (value: DropdownSize['maxWidth'] | Unit | undefined): string | undefined => {
+    if (value === undefined) {
+        return undefined;
+    }
+    if (value === DropdownSizeUnit.Viewport) {
+        return 'initial';
+    }
+    return isUnit(value) ? undefined : value;
+};
+
+export const getWidthValue = (
+    width: DropdownSize['width'] | undefined,
+    anchorRect: DOMRect | null | undefined,
+    contentRect: DOMRect | null | undefined
+): string | undefined => {
+    switch (width) {
+        case DropdownSizeUnit.Anchor:
+            return anchorRect ? `${anchorRect.width}px` : undefined;
+        case DropdownSizeUnit.Static:
+            return contentRect ? `${contentRect.width}px` : undefined;
+        case DropdownSizeUnit.Dynamic:
+        case undefined:
+            return undefined;
+        default:
+            return width;
+    }
+};
+
+export const getHeightValue = (
+    height: DropdownSize['height'] | undefined,
+    anchorRect: DOMRect | null | undefined,
+    contentRect: DOMRect | null | undefined
+): string | undefined => {
+    switch (height) {
+        case DropdownSizeUnit.Static:
+            return contentRect ? `${contentRect.height}px` : undefined;
+        case DropdownSizeUnit.Dynamic:
+        case DropdownSizeUnit.Anchor:
+        case undefined:
+            return undefined;
+        default:
+            return height;
+    }
+};
+
+export const getProp = (prop: string, value: string | undefined): Record<string, string> | undefined =>
+    value !== undefined ? { [prop]: value } : undefined;

