+/**
+ * The prefixes of the technical fields which are not part of the entity model and must not be
+ * sent to the server or persisted.
+ */
+const TECHNICAL_FIELD_PREFIXES = ["_finalEncrypted", "_defaultEncrypted", "_errors"]
+
+function isTechnicalField(name: string): boolean {
+	return TECHNICAL_FIELD_PREFIXES.some((prefix) => name.startsWith(prefix))
+}
+
+/**
+ * Removes all technical fields (properties starting with "_finalEncrypted", "_defaultEncrypted" or "_errors")
+ * from the given entity and from any nested objects it contains.
+ *
+ * The input entity is mutated. Entities without any technical fields remain unchanged.
+ * This should only be applied to new entities; after calling this function the object is no longer
+ * suitable for update operations.
+ *
+ * @param entity The entity to clean up.
+ */
+export function removeTechnicalFields<E extends SomeEntity>(entity: E): void {
+	for (const key of Object.keys(entity)) {
+		if (isTechnicalField(key)) {
+			delete (entity as Record<string, any>)[key]
+		} else {
+			const value = (entity as Record<string, any>)[key]
+			if (value != null && typeof value === "object") {
+				if (Array.isArray(value)) {
+					for (const item of value) {
+						if (item != null && typeof item === "object" && !Array.isArray(item) && !(item instanceof Uint8Array) && !(item instanceof Date)) {
+							removeTechnicalFields(item as E)
+						}
+					}
+				} else if (!(value instanceof Uint8Array) && !(value instanceof Date)) {
+					removeTechnicalFields(value as E)
+				}
+			}
+		}
+	}
+}

