+/**
+ * Returns a full url for the given social media id.
+ *
+ * Known social media types (Twitter, Facebook, LinkedIn, Xing) are mapped to their standard base
+ * path when the value lacks a scheme or "www". Values that already include a scheme or "www"
+ * are returned as-is (trimmed). For other or custom sites only "https://" (and "www." if missing)
+ * is added without appending a site-specific path.
+ */
+export function getSocialUrl(contactId: ContactSocialId): string {
+	let socialUrlType = ""
+	let http = "https://"
+	let worldwidew = "www."
+
+	switch (getContactSocialType(contactId)) {
+		case ContactSocialType.TWITTER:
+			socialUrlType = "twitter.com/"
+
+			if (contactId.socialId.indexOf("http") !== -1 || contactId.socialId.indexOf(worldwidew) !== -1) {
+				socialUrlType = ""
+			}
+
+			break
+
+		case ContactSocialType.FACEBOOK:
+			socialUrlType = "facebook.com/"
+
+			if (contactId.socialId.indexOf("http") !== -1 || contactId.socialId.indexOf(worldwidew) !== -1) {
+				socialUrlType = ""
+			}
+
+			break
+
+		case ContactSocialType.XING:
+			socialUrlType = "xing.com/profile/"
+
+			if (contactId.socialId.indexOf("http") !== -1 || contactId.socialId.indexOf(worldwidew) !== -1) {
+				socialUrlType = ""
+			}
+
+			break
+
+		case ContactSocialType.LINKED_IN:
+			socialUrlType = "linkedin.com/in/"
+
+			if (contactId.socialId.indexOf("http") !== -1 || contactId.socialId.indexOf(worldwidew) !== -1) {
+				socialUrlType = ""
+			}
+	}
+
+	if (contactId.socialId.indexOf("http") !== -1) {
+		http = ""
+	}
+
+	if (contactId.socialId.indexOf(worldwidew) !== -1) {
+		worldwidew = ""
+	}
+
+	return `${http}${worldwidew}${socialUrlType}${contactId.socialId.trim()}`
 }
